<section class="section-heading reveal">
    <div><h2>Типы балансов курсанта</h2><p>Настройте часы, денежные или количественные балансы, которые отображаются у каждого курсанта.</p></div>
    <div class="page-actions"><a class="button button--secondary" href="<?= e(url('/education/programs')) ?>"><?= icon('book-open', 17) ?> Учебные программы</a><a class="button button--secondary" href="<?= e(url('/education/checkpoints')) ?>"><?= icon('check-square', 17) ?> Контрольные точки</a></div>
</section>

<details class="panel stage-form-panel reveal" <?= !$types ? 'open' : '' ?>>
    <summary><span><?= icon('plus', 18) ?></span><strong>Добавить тип баланса</strong><small>Код, название, единица измерения и цвет</small></summary>
    <form method="post" action="<?= e(url('/education/balance-types')) ?>" class="stage-form"><div class="form-grid form-grid--three"><?= csrf_field() ?><label class="field"><span class="field__label">Название <b>*</b></span><span class="field__control"><input name="name" required maxlength="190" placeholder="Категория B"></span></label><label class="field"><span class="field__label">Код <b>*</b></span><span class="field__control"><input name="code" required maxlength="24" placeholder="B"></span></label><label class="field"><span class="field__label">Единица</span><span class="field__control"><select name="unit"><?php foreach ($units as $key => $label): ?><option value="<?= e($key) ?>"><?= e($label) ?></option><?php endforeach; ?></select></span></label><label class="field"><span class="field__label">Цвет</span><span class="field__control color-field"><input type="color" name="color" value="#4768db"><span>#</span></span></label><label class="field"><span class="field__label">Порядок</span><span class="field__control"><input type="number" name="sort_order" value="0"></span></label></div><input type="hidden" name="status" value="active"><div class="stage-form__actions"><button class="button button--primary" type="submit">Добавить тип</button></div></form>
</details>

<section class="panel reveal">
    <div class="data-table-wrap"><table class="data-table stage-table catalog-table"><thead><tr><th>Код</th><th>Название</th><th>Единица</th><th>Цвет</th><th>Порядок</th><th>Статус</th><th></th></tr></thead><tbody>
    <?php foreach ($types as $type): $formId = 'balance-type-' . (int) $type['id']; ?><tr><td><span class="balance-code" style="--chip-color:<?= e($type['color']) ?>"><?= e($type['code']) ?></span><input class="compact-code-input" form="<?= e($formId) ?>" name="code" value="<?= e($type['code']) ?>" required maxlength="24"></td><td><input form="<?= e($formId) ?>" name="name" value="<?= e($type['name']) ?>" required></td><td><select form="<?= e($formId) ?>" name="unit"><?php foreach ($units as $key => $label): ?><option value="<?= e($key) ?>" <?= $type['unit'] === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></td><td><input form="<?= e($formId) ?>" type="color" name="color" value="<?= e($type['color']) ?>"></td><td><input form="<?= e($formId) ?>" type="number" name="sort_order" value="<?= (int) $type['sort_order'] ?>"></td><td><select form="<?= e($formId) ?>" name="status"><option value="active" <?= $type['status'] === 'active' ? 'selected' : '' ?>>Используется</option><option value="archived" <?= $type['status'] === 'archived' ? 'selected' : '' ?>>Скрыт</option></select></td><td><form id="<?= e($formId) ?>" method="post" action="<?= e(url('/education/balance-types/' . $type['id'] . '/update')) ?>"><?= csrf_field() ?><button class="button button--secondary" type="submit">Сохранить</button></form></td></tr><?php endforeach; ?>
    <?php if (!$types): ?><tr><td colspan="7"><div class="empty-inline">Типов баланса пока нет.</div></td></tr><?php endif; ?>
    </tbody></table></div>
</section>
